seconds // dt_step) * dt_step\\n    start_dt = H0 + timedelta(seconds=start_seconds)\\n    end_dt = start_dt + timedelta(seconds=duration)\\n    if end_dt > H1:\\n        return set(), None\\n    if (duration % dt_step) != 0:\\n        return set(), None\\n\\n    # Sample times: start, start+cov_step, ..., end\\n    times = []\\n    t = start_dt\\n    wh\n\n[... truncated 6167 characters ...]\n\nn            v = np.array(state_best[3:6])\\n            x = v / np.linalg.norm(v)\\n            y = np.cross(z, x)\\n            y = y / np.linalg.norm(y)\\n            x = np.cross(y, z)\\n            x = x / np.linalg.norm(x)\\n            off_nadir = np.degrees(np.arccos(np.clip(np.dot(look_u, z), -1.0, 1.0)))\\n            sign = np.sign(np.dot(look_u, y))\\n            roll_center = sign * off_nadir\\n\\n            # Try a set of rolls around this\\n            rolls_to_try = []\\n            for offset in [-10, -5, 0, 5, 10]:\\n                r = roll_center + offset\\n                if abs(r) >= roll_min and abs(r) <= roll_max:\\n                    rolls_to_try.append(r)\\n            # also try extremes\\n            for r in [roll_min, roll_max, -roll_min, -roll_max]:\\n                if abs(r - roll_center) <= 15:\\n                    rolls_to_try.append(r)\\n            rolls_to_try = sorted(set(rolls_to_try), key=lambda r: abs(r - roll_center))\\n\\n            for roll in rolls_to_try:\\n                duration = max_dur\\n                start_dt = t_best - timedelta(seconds=duration/2)\\n                # align to dt_step\\n                start_sec = int(round((start_dt - H0).total_seconds()))\\n                start_sec = (start_sec // dt_step) * dt_step\\n                start_dt = H0 + timedelta(seconds=start_sec)\\n                end_dt = start_dt + timedelta(seconds=duration)\\n                if end_dt > H1:\\n                    end_dt = H1\\n                    duration = int((end_dt - start_dt).total_seconds())\\n                    duration